/**
 * Builder definition of the What's On module. Settings panels are generated by Divi
 * from module.json ("auto"); this file supplies the edit-mode renderer and styles.
 */
import React, { useEffect, useRef, useState } from 'react';
import {
	ModuleContainer,
	StyleContainer,
	CssStyle,
	TextStyle,
	elementClassnames,
	textOptionsClassnames,
} from '@divi/module';
import metadata from '../../../modules-json/events-carousel/module.json';
import { WhatsOnCarousel } from '../frontend/carousel-core';
import { builderOptions, queryString } from './options';

const builderData = () => window.WhatsOnBuilderData || {};

const moduleClassnames = ( { classnamesInstance, attrs } ) => {
	classnamesInstance.add( 'whats-on-module', true );
	classnamesInstance.add( textOptionsClassnames( attrs?.module?.advanced?.text ), true );
	classnamesInstance.add(
		elementClassnames( {
			attrs: {
				...( attrs?.module?.decoration ?? {} ),
				link: attrs?.module?.advanced?.link,
			},
		} )
	);
};

const ModuleStyles = ( { attrs, elements, settings, orderClass, mode, state, noStyleTag } ) => (
	<StyleContainer mode={ mode } state={ state } noStyleTag={ noStyleTag }>
		{ elements.style( {
			attrName: 'module',
			styleProps: {
				disabledOn: { disabledModuleVisibility: settings?.disabledModuleVisibility },
			},
		} ) }
		<TextStyle selector={ orderClass } attr={ attrs?.module?.advanced?.text } />
		{ elements.style( { attrName: 'card' } ) }
		{ elements.style( { attrName: 'image' } ) }
		{ elements.style( { attrName: 'title' } ) }
		{ elements.style( { attrName: 'date' } ) }
		{ elements.style( {
			attrName: 'arrows',
			styleProps: {
				advancedStyles: [
					{
						componentName: 'divi/common',
						props: {
							selector: `${ orderClass } .whats-on__nav`,
							attr: attrs?.arrows?.advanced?.color,
							property: 'color',
						},
					},
				],
			},
		} ) }
		<CssStyle selector={ orderClass } attr={ attrs?.css } cssFields={ metadata.customCssFields } />
	</StyleContainer>
);

/** Fetches the same events the front end would render, via whats-on/v1/events. */
const useEvents = ( query ) => {
	const [ result, setResult ] = useState( { status: 'loading', events: [] } );

	useEffect( () => {
		const { restUrl, nonce } = builderData();
		if ( ! restUrl ) {
			setResult( { status: 'error', events: [], message: 'What’s On builder data is missing.' } );
			return undefined;
		}

		const controller = new AbortController();
		setResult( ( previous ) => ( { ...previous, status: 'loading' } ) );

		fetch( `${ restUrl }${ restUrl.includes( '?' ) ? '&' : '?' }${ query }`, {
			credentials: 'same-origin',
			headers: { 'X-WP-Nonce': nonce || '' },
			signal: controller.signal,
		} )
			.then( ( response ) => {
				if ( ! response.ok ) {
					throw new Error( `HTTP ${ response.status }` );
				}
				return response.json();
			} )
			.then( ( body ) =>
				setResult( {
					status: 'ready',
					events: body.events || [],
					calendarActive: body.calendarActive,
				} )
			)
			.catch( ( error ) => {
				if ( error.name !== 'AbortError' ) {
					setResult( { status: 'error', events: [], message: error.message } );
				}
			} );

		return () => controller.abort();
	}, [ query ] );

	return result;
};

const Chevron = () => (
	<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false">
		<path d="M15.4 5.4 14 4l-8 8 8 8 1.4-1.4L8.8 12z" fill="currentColor" />
	</svg>
);

const Notice = ( { children } ) => (
	<div className="whats-on whats-on--empty">
		<p className="whats-on__empty">{ children }</p>
	</div>
);

const Carousel = ( { events, options } ) => {
	const rootRef = useRef( null );
	const Heading = options.headingLevel;

	// Re-attach the shared carousel behaviour whenever the rendered cards change.
	useEffect( () => {
		if ( ! rootRef.current ) {
			return undefined;
		}
		const carousel = new WhatsOnCarousel( rootRef.current );
		return () => carousel.destroy();
	}, [ events, options.loop, options.showArrows ] );

	return (
		<div
			ref={ rootRef }
			className="whats-on"
			data-whats-on=""
			data-loop={ options.loop ? 'on' : 'off' }
			style={ options.style }
			role="region"
			aria-roledescription="carousel"
			aria-label="What's On"
		>
			<div className="whats-on__viewport">
				<ul className="whats-on__track" role="list" tabIndex={ 0 }>
					{ events.map( ( event, index ) => (
						<li
							key={ event.id }
							className="whats-on__slide"
							role="group"
							aria-roledescription="slide"
							aria-label={ `${ index + 1 } of ${ events.length }` }
						>
							{ /* Links are inert inside the builder so clicks select the module. */ }
							<a className="whats-on__card" href={ event.url } onClick={ ( e ) => e.preventDefault() }>
								{ event.image ? (
									<div className="whats-on__image">
										<img
											src={ event.image.src }
											srcSet={ event.image.srcset || undefined }
											sizes={ event.image.srcset ? event.image.sizes : undefined }
											alt={ event.image.alt }
											width={ event.image.width || undefined }
											height={ event.image.height || undefined }
										/>
									</div>
								) : (
									<div className="whats-on__image whats-on__image--placeholder" aria-hidden="true" />
								) }
								<div className="whats-on__body">
									<Heading className="whats-on__title">{ event.title }</Heading>
									<p className="whats-on__date">
										<time dateTime={ event.start }>{ event.dateText }</time>
									</p>
								</div>
							</a>
						</li>
					) ) }
				</ul>
			</div>
			{ options.showArrows && (
				<>
					<button type="button" className="whats-on__nav whats-on__nav--prev" data-whats-on-prev="" aria-label="Previous events">
						<Chevron />
					</button>
					<button type="button" className="whats-on__nav whats-on__nav--next" data-whats-on-next="" aria-label="Next events">
						<Chevron />
					</button>
				</>
			) }
		</div>
	);
};

const EventsCarouselEdit = ( { attrs, elements, id, name } ) => {
	const options = builderOptions( attrs );
	const { status, events, message, calendarActive } = useEvents( queryString( options ) );

	let body;
	if ( status === 'error' ) {
		body = <Notice>{ `Could not load events: ${ message }` }</Notice>;
	} else if ( status === 'ready' && calendarActive === false ) {
		body = <Notice>The Events Calendar plugin is not active.</Notice>;
	} else if ( status === 'ready' && events.length === 0 ) {
		body = <Notice>{ options.noEventsText || 'There are no upcoming events at the moment.' }</Notice>;
	} else if ( events.length === 0 ) {
		body = <Notice>Loading events…</Notice>;
	} else {
		body = <Carousel events={ events } options={ options } />;
	}

	return (
		<ModuleContainer
			attrs={ attrs }
			elements={ elements }
			id={ id }
			name={ name }
			stylesComponent={ ModuleStyles }
			classnamesFunction={ moduleClassnames }
		>
			{ elements.styleComponents( { attrName: 'module' } ) }
			{ body }
		</ModuleContainer>
	);
};

export const eventsCarouselModule = {
	metadata,
	renderers: {
		edit: EventsCarouselEdit,
	},
};
